/* СУДОКУ на листе. Поле — B3:J11: клетки без заливки, чтобы рамки квадратов 3×3
   были видны. Цифры условия — тёмные и полужирные, свои — синие, повторы — красные.
   Ввод ловится событием «приИзменении»: плагин сам решает, что это — цифра, пометки
   или попытка поправить условие (тогда возвращает его на место).
   Задача и ход партии хранятся в памяти листа. */

/* ===== Поле на клетках листа: общий кусок игр магазина =====
   Строки и столбцы здесь — С НУЛЯ (r, c); адреса A1 считаются отсюда же.
   ячейка(строка, столбец) API плагина считает с единицы — поэтому везде «+ 1». */
const БУКВА = c => { let s = '', n = c + 1; while(n > 0){ const m = (n - 1) % 26; s = String.fromCharCode(65 + m) + s; n = (n - 1 - m) / 26; } return s; };
const АДРЕС = (r, c) => БУКВА(c) + (r + 1);
const ОБЛАСТЬ = (r1, c1, r2, c2) => АДРЕС(r1, c1) + ':' + АДРЕС(r2, c2);
const клетка = (r, c) => ячейка(r + 1, c + 1);
/* Квадратные клетки: ширина столбца в знаках (знак — 7 точек), высота строки в пунктах (×4/3 точки). */
function клеткиКвадратом(r1, c1, r2, c2, точек){
  const о = Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r1, c1, r2, c2));
  о.SetColumnWidth(точек / 7);
  о.SetRowHeight(точек * 0.75);
}
/* Вернуть области обычные размеры клеток (столбец 92 точки, строка 24 точки = 18 пунктов). */
function обычныеРазмеры(r1, c1, r2, c2){
  const о = Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r1, c1, r2, c2));
  о.SetColumnWidth(92 / 7);
  о.SetRowHeight(18);
}
/* Ширина одного столбца и высота одной строки в точках экрана. */
function ширинаСтолбца(c, точек){ Api.GetActiveSheet().GetRange(ОБЛАСТЬ(0, c, 0, c)).SetColumnWidth(точек / 7); }
function высотаСтроки(r, точек){ Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r, 0, r, 0)).SetRowHeight(точек * 0.75); }
/* Приложение запоминает смещения строк и не сбрасывает их, когда плагин меняет высоты строк:
   после этого щелчок мыши попадает не в ту клетку. Пустая запись в далёкую пустую строку
   растит сетку листа, и смещения пересчитываются. Звать после смены высот. */
async function обновитьВысоты(){
  /* каждый раз — строка дальше прежней: сетка растёт, только если запись за её краем */
  let n = 0; try { n = +лист().память('высоты-шаг') || 0; } catch(e){}
  for(let k = n + 1; k <= n + 40; k++){
    const r = 5999 + k;
    let v = null;
    try { v = await клетка(r, 0).прочитать(); } catch(e){ continue; }
    if(v === null || v === undefined || v === ''){
      клетка(r, 0).значение = null;
      try { лист().запомнить('высоты-шаг', k); } catch(e){}
      return true;
    }
  }
  return false;
}
/* Курсор — на «стоянку» рядом с полем. Тогда повторный щелчок по той же клетке
   снова сменит выделение, и плагин получит событие: иначе второй щелчок молчал бы. */
function наСтоянку(r, c){ клетка(r, c).выделить(); }
/* Пуста ли область листа: игра не должна молча затирать чужие данные. */
async function областьПуста(r1, c1, r2, c2){
  const строки = await диапазон(ОБЛАСТЬ(r1, c1, r2, c2)).прочитать();
  for(const ряд of строки || []) for(const v of ряд || []) if(v !== null && v !== undefined && v !== '') return false;
  return true;
}
/* Рамка: все четыре стороны одним видом. */
const РАМКА = (вид, цвет) => ({в: {вид, цвет}, н: {вид, цвет}, л: {вид, цвет}, п: {вид, цвет}});
/* Число со словом в нужной форме: число(5, 'выстрел', 'выстрела', 'выстрелов') → «5 выстрелов». */
function число(n, одна, две, пять){ const a = Math.abs(n) % 100, b = a % 10;
  return n + ' ' + (a > 10 && a < 20 ? пять : b === 1 ? одна : b >= 2 && b <= 4 ? две : пять); }
/* Время «м:сс». */
const ВРЕМЯ = с => Math.floor(с / 60) + ':' + String(Math.floor(с % 60)).padStart(2, '0');
/* Повод события — клетка с нуля и на нужном ли листе. */
function гдеЩелчок(п, лист){
  if(!п || !п.адрес || (лист && п.лист !== лист)) return null;
  if(п.клеток > 1) return null;                     /* протянули мышью область — это не ход */
  return {r: п.строка - 1, c: п.столбец - 1};
}
/* Защита от «правой кнопки»: правый щелчок сначала зовёт меню, а через 150 мс
   приходит выделение той же клетки. Такой выбор ходом не считаем. */
let последнееМеню = {адрес: '', t: 0};
const этоПослеМеню = п => п && п.адрес === последнееМеню.адрес && Date.now() - последнееМеню.t < 1500;
/* ===== конец общего куска ===== */
/* Оформление области по клеткам. Api GetRange(…).SetNumberFormat и другие оформления области из потока
   задевают только ту часть, что была занята при запуске потока, — свежие строки остаются без оформления.
   л — лист плагина: лист(имя) или черновик; строки и столбцы — с нуля. */
function оформитьОбласть(л, r1, c1, r2, c2, стиль){
  if((r2 - r1 + 1) * (c2 - c1 + 1) > 300000) return false;
  for(let r = r1; r <= r2; r++) for(let c = c1; c <= c2; c++) л.ячейка(r + 1, c + 1).стиль = стиль;
  return true;
}

const Р0 = 2, С0 = 1, ТОЧЕК = 32, ПАМЯТЬ = 'судоку';
const ЦВ = {условие: '#151c2e', свои: '#296DF4', ошибка: '#dc2626', пометка: '#7b8496'};
let игра = null, тик = null, сНачала = 0;

/* --- случайность с зерном: «судоку дня» одинаково у всех ------------------ */
function зерно(s){ return function(){ s |= 0; s = s + 0x6D2B79F5 | 0; let t = Math.imul(s ^ s >>> 15, 1 | s); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; }; }
let слу = Math.random;
const перемешать = м => { for(let i = м.length - 1; i > 0; i--){ const j = Math.floor(слу() * (i + 1)); [м[i], м[j]] = [м[j], м[i]]; } return м; };

/* --- поле: 81 число, 0 — пусто -------------------------------------------- */
const РЯД = i => Math.floor(i / 9), СТЛ = i => i % 9, КВ = i => Math.floor(РЯД(i) / 3) * 3 + Math.floor(СТЛ(i) / 3);
const ЕДИНИЦЫ = [];          /* 27 групп: 9 строк, 9 столбцов, 9 квадратов */
for(let k = 0; k < 9; k++){
  ЕДИНИЦЫ.push([...Array(9)].map((_, j) => k * 9 + j));
  ЕДИНИЦЫ.push([...Array(9)].map((_, j) => j * 9 + k));
  ЕДИНИЦЫ.push([...Array(9)].map((_, j) => (Math.floor(k / 3) * 3 + Math.floor(j / 3)) * 9 + (k % 3) * 3 + j % 3));
}
const СОСЕДИ = [...Array(81)].map((_, i) => { const s = new Set(); for(const u of ЕДИНИЦЫ) if(u.includes(i)) for(const j of u) if(j !== i) s.add(j); return [...s]; });
function кандидаты(п, i){ if(п[i]) return 0; let m = 0x3FE; for(const j of СОСЕДИ[i]) if(п[j]) m &= ~(1 << п[j]); return m; }
const биты = m => { const r = []; for(let d = 1; d <= 9; d++) if(m & (1 << d)) r.push(d); return r; };

/* решатель перебором: считает решения до «предела» (2 — проверка единственности) */
function решений(п, предел, перемешивать){
  п = п.slice(); let найдено = 0, первое = null;
  (function шаг(){
    if(найдено >= предел) return;
    let лучшая = -1, лучшие = null, мин = 10;
    for(let i = 0; i < 81; i++) if(!п[i]){ const к = биты(кандидаты(п, i)); if(к.length < мин){ мин = к.length; лучшая = i; лучшие = к; if(!мин) return; } }
    if(лучшая < 0){ найдено++; if(!первое) первое = п.slice(); return; }
    for(const d of (перемешивать ? перемешать(лучшие) : лучшие)){ п[лучшая] = d; шаг(); if(найдено >= предел) return; }
    п[лучшая] = 0;
  })();
  return {найдено, первое};
}
/* логический решатель: одиночки и скрытые одиночки; что смог — возвращает */
function логикой(п, приём){
  п = п.slice();
  for(;;){
    const ход = следующийХод(п);
    if(!ход) return п;
    if(приём && !приём.has(ход.приём)) return п;
    п[ход.i] = ход.d;
  }
}
function следующийХод(п){
  for(let i = 0; i < 81; i++) if(!п[i]){ const к = биты(кандидаты(п, i)); if(к.length === 1) return {i, d: к[0], приём: 'одиночка'}; }
  for(let u = 0; u < 27; u++){
    const ед = ЕДИНИЦЫ[u];
    for(let d = 1; d <= 9; d++){
      if(ед.some(j => п[j] === d)) continue;
      const места = ед.filter(j => !п[j] && (кандидаты(п, j) & (1 << d)));
      if(места.length === 1) return {i: места[0], d, приём: 'скрытая', ед: u};
    }
  }
  return null;
}
const решеноЛи = п => п.every(x => x);
function создать(уровень){
  const цель = {'Лёгкий': 38, 'Средний': 30, 'Сложный': 25}[уровень] || 30;
  for(let попытка = 0; попытка < 40; попытка++){
    const полное = решений(new Array(81).fill(0), 1, true).первое;
    const задача = полное.slice();
    let открыто = 81;
    for(const i of перемешать([...Array(81).keys()])){
      if(открыто <= цель) break;
      const было = задача[i]; задача[i] = 0;
      if(решений(задача, 2, false).найдено !== 1) задача[i] = было; else открыто--;
    }
    const одиночками = решеноЛи(логикой(задача, new Set(['одиночка'])));
    const скрытыми = решеноЛи(логикой(задача));
    if(уровень === 'Лёгкий' && одиночками) return {задача, решение: полное};
    if(уровень === 'Средний' && скрытыми && !одиночками) return {задача, решение: полное};
    if(уровень === 'Сложный' && !скрытыми) return {задача, решение: полное};
    if(попытка > 30 && (уровень !== 'Сложный' || открыто <= цель + 2)) return {задача, решение: полное};
  }
  const полное = решений(new Array(81).fill(0), 1, true).первое, задача = полное.slice();
  for(const i of перемешать([...Array(81).keys()]).slice(0, 45)){ const было = задача[i]; задача[i] = 0; if(решений(задача, 2, false).найдено !== 1) задача[i] = было; }
  return {задача, решение: полное};
}

/* --- рисование ------------------------------------------------------------- */
const клеткаПоля = i => клетка(Р0 + РЯД(i), С0 + СТЛ(i));
function рамки(i){
  const r = РЯД(i), c = СТЛ(i), т = '#9aa4b5', ж = '#151c2e';
  return {в: {вид: r % 3 === 0 ? 'средняя' : 'тонкая', цвет: r % 3 === 0 ? ж : т},
          н: {вид: r === 8 ? 'средняя' : 'тонкая', цвет: r === 8 ? ж : т},
          л: {вид: c % 3 === 0 ? 'средняя' : 'тонкая', цвет: c % 3 === 0 ? ж : т},
          п: {вид: c === 8 ? 'средняя' : 'тонкая', цвет: c === 8 ? ж : т}};
}
function повторы(){
  const п = игра.задача.map((x, i) => x || игра.ввод[i]), плохие = new Set();
  for(const ед of ЕДИНИЦЫ){ const где = {}; for(const j of ед) if(п[j]) (где[п[j]] = где[п[j]] || []).push(j);
    for(const d in где) if(где[d].length > 1) for(const j of где[d]) if(!игра.задача[j]) плохие.add(j); }
  return плохие;
}
function нарисоватьКлетку(i, плохие){
  const к = клеткаПоля(i), осн = {align: 'center', valign: 'middle', гр: рамки(i), fill: null, wrap: false};
  if(игра.задача[i]){ к.значение = игра.задача[i]; к.стиль = Object.assign(осн, {b: 1, size: 16, color: ЦВ.условие}); return; }
  if(игра.ввод[i]){ к.значение = игра.ввод[i]; к.стиль = Object.assign(осн, {b: 0, size: 16, color: плохие && плохие.has(i) ? ЦВ.ошибка : ЦВ.свои}); return; }
  if(игра.пометки[i]){ к.значение = String(игра.пометки[i]).split('').join(' '); к.стиль = Object.assign(осн, {b: 0, size: 7, color: ЦВ.пометка, wrap: true}); return; }
  к.значение = ''; к.стиль = Object.assign(осн, {b: 0, size: 16, color: ЦВ.свои});
}
function нарисоватьВсё(){
  const плохие = параметры({}).подсветка === false ? null : повторы();
  for(let i = 0; i < 81; i++) нарисоватьКлетку(i, плохие);
  шапка();
}
function шапка(){
  const к = клетка(0, С0);
  к.значение = 'Судоку · ' + игра.уровень + (игра.конец ? ' · решено за ' + ВРЕМЯ(игра.секунд) : '');
  к.стиль = {b: 1, size: 12, color: игра.конец ? '#15803d' : '#151c2e'};
}
const прошло = () => игра && !игра.конец && сНачала ? Math.floor((Date.now() - сНачала) / 1000) : (игра ? игра.секунд || 0 : 0);
function сохранить(){ лист(игра.лист).запомнить(ПАМЯТЬ, Object.assign({}, игра, {секунд: прошло()})); }
function показатьСчёт(){
  if(!игра){ панель.список('сейчас', [['Игра', 'нажмите «Новая игра»']]); return; }
  const пусто = игра.задача.reduce((s, x, i) => s + (!x && !игра.ввод[i] ? 1 : 0), 0);
  панель.список('сейчас', [['Уровень', игра.уровень], ['Время', ВРЕМЯ(прошло())], ['Осталось клеток', String(пусто)],
    ['Подсказок', String(игра.подсказок || 0)], ['Итог', игра.конец ? 'решено!' : 'идёт']]);
}
function показатьРекорды(){
  const р = хранилище.взять('рекорды', {}) || {};
  панель.список('рекорды', ['Лёгкий', 'Средний', 'Сложный', 'Судоку дня'].map(к => [к, р[к] != null ? ВРЕМЯ(р[к]) : '—']));
}
function часы(вкл){ if(вкл && !тик) тик = setInterval(показатьСчёт, 1000); if(!вкл && тик){ clearInterval(тик); тик = null; } }
function проверитьКонец(){
  for(let i = 0; i < 81; i++) if(!игра.задача[i] && игра.ввод[i] !== игра.решение[i]) return false;
  игра.секунд = прошло(); игра.конец = true; часы(false);
  const р = хранилище.взять('рекорды', {}) || {}, ключ = игра.уровень;
  const рекорд = !игра.подсказок && (р[ключ] == null || игра.секунд < р[ключ]);
  if(рекорд){ р[ключ] = игра.секунд; хранилище.положить('рекорды', р); показатьРекорды(); }
  панель.сообщение('Решено за ' + ВРЕМЯ(игра.секунд) + (рекорд ? ' — новый рекорд!' : игра.подсказок ? ' (с подсказками рекорд не засчитывается)' : '') + '.');
  return true;
}

/* --- обработчики ----------------------------------------------------------- */
function Старт(){
  показатьРекорды();
  let м = null; try { м = лист().память(ПАМЯТЬ); } catch(e){}
  if(м && м.задача && !м.конец){ игра = м; сНачала = Date.now() - (игра.секунд || 0) * 1000; часы(true);
    панель.сообщение('Незаконченная судоку на этом листе — продолжаем.'); }
  показатьСчёт();
}
async function НоваяИгра(){
  const уровень = параметры({}).уровень || 'Средний';
  let своё = null; try { своё = лист().память(ПАМЯТЬ); } catch(e){}
  if(!своё && !(await областьПуста(0, С0, Р0 + 8, С0 + 8))){
    if(!(await диалог.вопрос('На этом листе в B1:J11 уже что-то есть. Поле судоку ляжет поверх. Лучше завести пустой лист (+ внизу). Всё равно положить здесь?'))) return;
  }
  часы(false);
  let ур = уровень;
  if(уровень === 'Судоку дня'){ const д = new Date(); слу = зерно(д.getFullYear() * 10000 + (д.getMonth() + 1) * 100 + д.getDate()); ур = 'Средний'; }
  else слу = Math.random;
  панель.сообщение('Составляю задачу…');
  const {задача, решение} = создать(ур);
  игра = {лист: книга.выделение ? книга.выделение.лист : книга.листы[0], уровень, задача, решение,
          ввод: new Array(81).fill(0), пометки: new Array(81).fill(''), секунд: 0, конец: false, подсказок: 0};
  клеткиКвадратом(Р0, С0, Р0 + 8, С0 + 8, ТОЧЕК);
  await обновитьВысоты();
  нарисоватьВсё(); сохранить();
  сНачала = Date.now(); часы(true); показатьСчёт();
  const перв = задача.findIndex(x => !x); if(перв >= 0) клеткаПоля(перв).выделить();
  панель.сообщение('Новая судоку: ' + уровень + ', открыто ' + задача.filter(x => x).length + ' клеток из 81.');
}
function Правка(){
  const п = книга.повод;
  if(!игра || п.строение || п.откуда === 'плагин') return;
  let менялось = false;
  for(const к of п.клетки || []){
    if(к.лист !== игра.лист) continue;
    const r = к.строка - 1 - Р0, c = к.столбец - 1 - С0;
    if(r < 0 || c < 0 || r > 8 || c > 8) continue;
    const i = r * 9 + c; менялось = true;
    if(игра.задача[i] || игра.конец) continue;            /* условие и решённое поле не правятся — перерисуем */
    const t = String(к.значение == null ? '' : к.значение).replace(/[^1-9]/g, '');
    if(t.length === 1){ игра.ввод[i] = +t; игра.пометки[i] = ''; }
    else if(t.length > 1){ игра.ввод[i] = 0; игра.пометки[i] = [...new Set(t.split(''))].sort().join(''); }
    else { игра.ввод[i] = 0; игра.пометки[i] = ''; }
  }
  if(!менялось) return;
  нарисоватьВсё();
  if(!игра.конец) проверитьКонец();
  шапка(); сохранить(); показатьСчёт();
}
function Подсказка(){
  if(!игра || игра.конец) return;
  /* сначала ошибки: подсказка поверх неверной цифры только запутает */
  const неверно = [];
  for(let i = 0; i < 81; i++) if(!игра.задача[i] && игра.ввод[i] && игра.ввод[i] !== игра.решение[i]) неверно.push(i);
  if(неверно.length){ панель.сообщение('Сначала проверьте ' + АДРЕС(Р0 + РЯД(неверно[0]), С0 + СТЛ(неверно[0])) + ': эта цифра не сходится с решением' + (неверно.length > 1 ? ' (и ещё ' + (неверно.length - 1) + ')' : '') + '.'); клеткаПоля(неверно[0]).выделить(); return; }
  const п = игра.задача.map((x, i) => x || игра.ввод[i]);
  const ход = следующийХод(п);
